import XCTest

class ElementUITest: XCTestCase {
    func testOpenTeamStandupAndSearch() {
        let app = XCUIApplication()

        // Tap on the Team Standup room
        let teamStandupElement = app.cells.staticTexts["Team Standup"].firstMatch
        if teamStandupElement.waitForExistence(timeout: 2) {
            teamStandupElement.tap()
        } else {
            // Try alternative: tap on the cell containing the text
            let cells = app.cells
            for cell in cells.allElementsBoundByIndex {
                if cell.staticTexts["Team Standup"].exists {
                    cell.tap()
                    break
                }
            }
        }

        sleep(1)
    }
}
EOF
echo "XCTest file created"
